## Stripe Subscription Checkout Create

**Endpoint:** POST /webhook/subscription-checkout-create

**Purpose:** Creates a Stripe Checkout session for subscription signup.
Acts as a proxy - each project has its own Stripe account.

**Input:**
```json
{
  "project_id": "torah",
  "price_id": "price_xxx",
  "customer_email": "user@example.com",
  "callbacks": {
    "success": "http://...",
    "renewal": "http://..."
  },
  "urls": {
    "success": "https://...",
    "cancel": "https://..."
  },
  "metadata": {},
  "options": {
    "trial_days": 7
  }
}
```

**Output:**
```json
{
  "success": true,
  "checkout_url": "https://checkout.stripe.com/...",
  "session_id": "cs_xxx"
}
```

**Setup:** Utilise Redis pour la config projet (cle: project:{project_id})

parameters.jsCode:
// Validate and extract input parameters
const input = $input.first().json;
const body = input.body || {};

// Required fields
const requiredFields = ['project_id', 'price_id', 'customer_email', 'urls'];
const missing = requiredFields.filter(f => !body[f]);

if (missing.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Missing required fields: ${missing.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Validate URLs
if (!body.urls.success || !body.urls.cancel) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'urls.success and urls.cancel are required',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Extract and normalize data
return [{
  json: {
    valid: true,
    project_id: body.project_id,
    price_id: body.price_id,
    customer_email: body.customer_email,
    callbacks: body.callbacks || {},
    urls: body.urls,
    metadata: body.metadata || {},
    options: body.options || {},
    redis_key: `project:${body.project_id}`
  }
}];

// Check if project was found in Redis
const redisResult = $('Get Stripe Config (Redis)').first();
const inputData = $('Validate Input').first().json;

// Redis retourne la valeur dans propertyName, value, ou directement
const redisJson = redisResult?.json || {};
const rawValue = redisJson.propertyName || redisJson.value || redisJson;

// Verifier si Redis a retourne une erreur
if (redisJson.error || JSON.stringify(redisJson).includes('ECONNREFUSED')) {
  return [{
    json: {
      found: false,
      error: {
        code: 503,
        message: 'Service Redis indisponible',
        status: 'SERVICE_UNAVAILABLE'
      }
    }
  }];
}

if (!rawValue || rawValue === null || rawValue === 'null') {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Project '${inputData.project_id}' not found. Call /stripe-register-project first.`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Parser le JSON stocke dans Redis
let project;
try {
  project = typeof rawValue === 'string' ? JSON.parse(rawValue) : rawValue;
} catch (e) {
  return [{
    json: {
      found: false,
      error: {
        code: 500,
        message: `Erreur parsing Redis: ${e.message}`,
        status: 'INTERNAL_ERROR'
      }
    }
  }];
}

if (!project.stripe_key) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Project '${inputData.project_id}' has no Stripe key configured`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Prepare body using manual encoding (URLSearchParams not available in n8n sandbox)
const encode = (str) => encodeURIComponent(String(str));
const parts = [];

parts.push(`mode=subscription`);
parts.push(`customer_email=${encode(inputData.customer_email)}`);
parts.push(`line_items[0][price]=${encode(inputData.price_id)}`);
parts.push(`line_items[0][quantity]=1`);
parts.push(`success_url=${encode(inputData.urls.success + '?session_id={CHECKOUT_SESSION_ID}')}`);
parts.push(`cancel_url=${encode(inputData.urls.cancel)}`);
parts.push(`metadata[project_id]=${encode(inputData.project_id)}`);

// Add callbacks to metadata
if (inputData.callbacks.success) {
  parts.push(`metadata[callback_success]=${encode(inputData.callbacks.success)}`);
}
if (inputData.callbacks.renewal) {
  parts.push(`metadata[callback_renewal]=${encode(inputData.callbacks.renewal)}`);
}
if (inputData.callbacks.failure) {
  parts.push(`metadata[callback_failure]=${encode(inputData.callbacks.failure)}`);
}
if (inputData.callbacks.cancel) {
  parts.push(`metadata[callback_cancel]=${encode(inputData.callbacks.cancel)}`);
}

// Add custom metadata
if (inputData.metadata) {
  Object.entries(inputData.metadata).forEach(([key, value]) => {
    parts.push(`metadata[${encode(key)}]=${encode(value)}`);
  });
}

// Add trial if specified
if (inputData.options.trial_days) {
  parts.push(`subscription_data[trial_period_days]=${encode(inputData.options.trial_days)}`);
}

// Add coupon if specified
if (inputData.options.coupon_code) {
  parts.push(`discounts[0][coupon]=${encode(inputData.options.coupon_code)}`);
}

// Add promotion codes if enabled
if (inputData.options.allow_promotion_codes) {
  parts.push(`allow_promotion_codes=true`);
}

return [{
  json: {
    found: true,
    stripe_key: project.stripe_key,
    body_string: parts.join('&'),
    project_id: inputData.project_id
  }
}];

// Format success response
const stripeResponse = $input.first().json;

if (stripeResponse.statusCode === 200 && stripeResponse.body) {
  const session = stripeResponse.body;
  return [{
    json: {
      success: true,
      checkout_url: session.url,
      session_id: session.id,
      expires_at: new Date(session.expires_at * 1000).toISOString()
    }
  }];
}

// Handle Stripe error
const error = stripeResponse.body?.error || {};
return [{
  json: {
    success: false,
    error: {
      code: stripeResponse.statusCode || 500,
      message: error.message || 'Failed to create checkout session',
      type: error.type || 'api_error',
      stripe_code: error.code || null
    }
  }
}];

